"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"

/** 1.7778 to 16 : 9. Finds the smallest denominator up to 20 that lands on a whole number. */
function toFraction(ratio: number): [number, number] {
  for (let b = 1; b <= 20; b++) if (Math.abs(ratio * b - Math.round(ratio * b)) < 0.01) return [Math.round(ratio * b), b]
  return [Math.round(ratio * 10), 10]
}

type AspectRatioProps = React.ComponentProps<"div"> & {
  /** Width over height. 16 / 9 by default. */
  ratio?: number
  /**
   * What sits in the frame's middle. true draws the ratio as a fraction (16 over 9);
   * it rolls when the ratio changes. Anything else is shown as given.
   */
  label?: React.ReactNode
  /**
   * crop: the printer's crop marks only.
   * diagonal: the scaling diagonal, corner to corner, with the ratio written along it.
   * square: the largest square ruled off, and what's left named by its own ratio.
   */
  variant?: "crop" | "diagonal" | "square"
}

const gcd = (x: number, y: number): number => (y ? gcd(y, x % y) : x)

/** A frame kept to a ratio and marked the way a printer marks a crop: short lines outside each corner, never a border. */
function AspectRatio({ ratio = 16 / 9, label, variant = "crop", className, style, children, ...props }: AspectRatioProps) {
  const [a, b] = toFraction(ratio)
  const orient = a > b ? "landscape" : a < b ? "portrait" : "square"
  // What's left once the square is ruled off: 16 : 9 leaves 7 : 9, 4 : 5 leaves 4 : 1.
  const rest = orient === "landscape" ? [a - b, b] : [a, b - a]
  const k = gcd(rest[0], rest[1]) || 1
  const [shown, setShown] = React.useState<[number, number]>([a, b])
  const before = React.useRef(ratio)
  const refs = React.useRef<[HTMLSpanElement | null, HTMLSpanElement | null]>([null, null])

  React.useEffect(() => {
    if (before.current === ratio) return
    const dir = ratio > before.current ? 1 : -1
    before.current = ratio
    const next = toFraction(ratio)
    // The numerator and the denominator each roll the way the ratio moved.
    refs.current.forEach((el, i) => el && roll(el, () => setShown((s) => (i ? [s[0], next[1]] : [next[0], s[1]])), "0.5em", dir))
  }, [ratio])

  return (
    <div
      data-slot="aspect-ratio"
      data-variant={variant}
      data-orient={orient}
      style={{ "--ratio": ratio, ...style } as React.CSSProperties}
      className={cn("db-ratio", className)}
      {...props}
    >
      {label === true ? (
        <span className="db-fraction" aria-hidden="true">
          <span ref={(el) => void (refs.current[0] = el)} className="db-yours">{shown[0]}</span>
          <i />
          <span ref={(el) => void (refs.current[1] = el)}>{shown[1]}</span>
        </span>
      ) : null}
      {label === true ? (
        <span className="db-sr">
          {a} by {b}
        </span>
      ) : (
        label
      )}
      {label === true && variant === "square" && orient !== "square" ? (
        // Keyed, so the name of what's left arrives again once the square has glided to its new place.
        <span key={`${orient} ${rest}`} className="db-ratio-rest" aria-hidden="true">
          <span className="db-fraction">
            <span>{rest[0] / k}</span>
            <i />
            <span>{rest[1] / k}</span>
          </span>
        </span>
      ) : null}
      {children}
    </div>
  )
}

export { AspectRatio, type AspectRatioProps }

@layer components {
  /* ── db-ratio ── a frame kept to a ratio, marked the way a printer marks a crop: trim marks, never a border */
  @property --ratio { syntax: "<number>"; inherits: false; initial-value: 1.7778; }
  .db-ratio {
    /* --ratio is registered so it can ease, and so it doesn't inherit; --r carries it to the parts and pseudo-elements. */
    --r: var(--ratio); --c: var(--db-ink); --line: var(--db-rule-strong);
    position: relative; display: grid; place-items: center; aspect-ratio: var(--ratio); container-type: inline-size;
    transition: --ratio var(--db-andante) var(--db-breath);
  }
  .db-ratio::before {
    --m: 12px; --g: 6px; --e: calc(var(--m) + var(--g));
    content: ""; position: absolute; inset: calc(-1 * var(--e)); pointer-events: none;
    background:
      linear-gradient(var(--c), var(--c)) 0 var(--e) / var(--m) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% var(--e) / var(--m) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 0 calc(100% - var(--e)) / var(--m) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% calc(100% - var(--e)) / var(--m) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) var(--e) 0 / var(--db-hairline) var(--m),
      linear-gradient(var(--c), var(--c)) calc(100% - var(--e)) 0 / var(--db-hairline) var(--m),
      linear-gradient(var(--c), var(--c)) var(--e) 100% / var(--db-hairline) var(--m),
      linear-gradient(var(--c), var(--c)) calc(100% - var(--e)) 100% / var(--db-hairline) var(--m);
    background-repeat: no-repeat;
  }
  .db-ratio > .db-fraction > *, .db-ratio-rest .db-fraction > * { display: inline-block; }
  /* The fraction keeps to the frame: full size in a wide one, smaller in a small one. */
  .db-ratio > .db-fraction { font-size: min(var(--db-f), 17cqi); }

  /* Diagonal: the paste-up artist's scaling line, from the foot of the start edge to the head of the end edge.
     Every frame whose corner lies on it has the same ratio. The ratio is written along it, standing on it,
     and swings with it as the frame eases. */
  .db-ratio[data-variant="diagonal"]::after {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    background: linear-gradient(to bottom right, transparent calc(50% - 0.6px), var(--line) calc(50% - 0.6px) calc(50% + 0.6px), transparent calc(50% + 0.6px));
  }
  .db-ratio[data-variant="diagonal"] > .db-fraction { transform: rotate(calc(-1 * atan2(1, var(--r)))) translateY(-62%); }
  .db-ratio[data-variant="diagonal"]:is([dir="rtl"], [dir="rtl"] *)::after { background: linear-gradient(to bottom left, transparent calc(50% - 0.6px), var(--line) calc(50% - 0.6px) calc(50% + 0.6px), transparent calc(50% + 0.6px)); }
  .db-ratio[data-variant="diagonal"]:is([dir="rtl"], [dir="rtl"] *) > .db-fraction { transform: rotate(atan2(1, var(--r))) translateY(-62%); }

  /* Square: the largest square ruled off from the start (or the head, when the frame stands tall),
     the ratio in the square and what's left named by its own, in the pencil. The rule glides as the frame eases;
     at 1 : 1 there is nothing left and it runs to nothing. */
  .db-ratio[data-variant="square"]::after {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    background:
      linear-gradient(var(--line), var(--line)) no-repeat calc(100% / var(--r)) 0 / var(--db-hairline) calc(clamp(0, (var(--r) - 1) * 1000, 1) * 100%),
      linear-gradient(var(--line), var(--line)) no-repeat 0 calc(var(--r) * 100%) / calc(clamp(0, (1 - var(--r)) * 1000, 1) * 100%) var(--db-hairline);
  }
  .db-ratio[data-variant="square"]:is([dir="rtl"], [dir="rtl"] *)::after { background-position: calc(100% - 100% / var(--r)) 0, 0 calc(var(--r) * 100%); }
  .db-ratio[data-variant="square"] > .db-fraction { position: absolute; display: flex; flex-wrap: wrap; place-content: center; }
  .db-ratio-rest { position: absolute; display: grid; place-items: center; animation: db-ratio-rest var(--db-moderato) var(--db-exhale) var(--db-andante) backwards; }
  @keyframes db-ratio-rest { from { opacity: 0; } }
  .db-ratio[data-variant="square"][data-orient="landscape"] > .db-fraction { inset-block: 0; inset-inline-start: 0; width: calc(100% / var(--r)); }
  .db-ratio[data-variant="square"][data-orient="portrait"] > .db-fraction { inset-inline: 0; inset-block-start: 0; height: calc(var(--r) * 100%); }
  .db-ratio-rest .db-fraction { font-size: min(var(--db-mp), 9cqi); }
  .db-ratio-rest .db-fraction > * { color: var(--db-pencil); }
  .db-ratio[data-orient="landscape"] > .db-ratio-rest { inset-block: 0; inset-inline: calc(100% / var(--r)) 0; }
  .db-ratio[data-orient="portrait"] > .db-ratio-rest { inset-inline: 0; inset-block: calc(var(--r) * 100%) 0; }

  /* Forced colours would drop the marks and lines, which are background images: keep them, in CanvasText. */
  @media (forced-colors: active) { .db-ratio { --c: CanvasText; --line: CanvasText; } .db-ratio::before, .db-ratio::after { forced-color-adjust: none; } }
}
